/** Replace recognizable English UI words when a legacy key has no explicit locale entry. */
export function localizeFallback(language: LanguageCode, source: string): string {
  if (language === 'en') return source;
  const placeholders: string[] = [];
  const masked = source.replace(/\{\{[^}]+\}\}/g, placeholder => {
    placeholders.push(placeholder);
    return `\u0000${placeholders.length - 1}\u0000`;
  });
  const phrases = phraseMaps[language] ?? {};
  const phraseLocalized = Object.entries(phrases).sort((a, b) => b[0].length - a[0].length).reduce((result, [phrase, replacement]) => result.replaceAll(phrase, replacement), masked);
  const map = { ...(wordMaps[language] ?? {}), ...(supplementalWordMaps[language] ?? {}), ...(coverageWordMaps[language] ?? {}) };
  const localized = phraseLocalized.replace(/\b[A-Za-z][A-Za-z'-]*\b/g, word => map[word] ?? word);
  return localized.replace(/\u0000(\d+)\u0000/g, (_, index: string) => placeholders[Number(index)] ?? '');
}
